44	std::string GetKernelTaskType(const ascir::FusedScheduledResult &schedule_results) {
45	  if (ascgen_utils::IsJustCubeFixpip(schedule_results)) {
46	    return kKernelTaskTypeAICOnly;
47	  } else if (ascgen_utils::IsCubeFusedScheduled(schedule_results)) {
48	    if (ascgen_utils::IsConv2DFusedScheduled(schedule_results)) {
49	      std::string npu_arch;
50	      GE_ASSERT_SUCCESS(ge::PlatformContext::GetInstance().GetCurrentPlatformString(npu_arch));
51	      if (npu_arch == "5102") {
52	        return kKernelTaskTypeMixAICOneOne;
53	      } else {
54	        return kKernelTaskTypeMixAICOneTwo;
55	      }
56	    } else {
57	      return kKernelTaskTypeMixAICOneTwo;
58	    }
59	  }
60	  return schedule_results.workspace_nodes.size() != 0 ? kKernelTaskTypeMixAIVOneZero : kKernelTaskTypeAIVOnly;
61	}
62	
63	std::string RemoveAutoFuseTilingHeadGuards(const std::string &input) {
64	  std::istringstream iss(input);
65	  std::ostringstream oss;
66	  std::string line;
67	
68	  while (std::getline(iss, line)) {
69	    // 如果当前行不包含 guard_token，则保留
70	    if (line.find(kTilingHeadGuard) == std::string::npos) {
71	      oss << line << "\n";
72	    }
73	  }
74	
75	  return oss.str();
76	}
77	
78	const void *GetAscirParamGraphKey(const ascir::ImplGraph &impl_graph) {
79	  const auto compute_graph = af::AscGraphUtils::GetComputeGraph(impl_graph);
80	  return compute_graph == nullptr ? static_cast<const void *>(&impl_graph)
81	                                  : static_cast<const void *>(compute_graph.get());
82	}
83	
84	Status EnrichScheduleGroupAscirParams(const ascir::ScheduleGroup &schedule_group,
85	                                      std::set<const void *> &enriched_graphs) {
86	  for (const auto &impl_graph : schedule_group.impl_graphs) {
87	    const auto graph_key = GetAscirParamGraphKey(impl_graph);
88	    if (!enriched_graphs.insert(graph_key).second) {
89	      continue;
90	    }
91	    GE_ASSERT_SUCCESS(ascir_param::EnrichAscirGraphNodeParams(impl_graph), "Enrich ascir node params failed.");
92	  }
93	  return af::SUCCESS;
94	}
95	
96	Status EnrichScheduledResultAscirParams(const ascir::FusedScheduledResult &fused_schedule_result) {
97	  std::set<const void *> enriched_graphs;
98	  for (const auto &asc_graph_results : fused_schedule_result.node_idx_to_scheduled_results) {
99	    for (const auto &scheduled_result : asc_graph_results) {
100	      for (const auto &schedule_group : scheduled_result.schedule_groups) {
101	        GE_ASSERT_SUCCESS(EnrichScheduleGroupAscirParams(schedule_group, enriched_graphs),
102	                          "Enrich ascir node params failed.");
103	      }
104	    }
105	  }
106	  return af::SUCCESS;
107	}
108	
109	bool IsSplitTilingHeaderKey(const std::string &key) {
110	  return key == kTilingStateHeaderIdentify || key == kTilingLogHeaderIdentify || key == kTilingPgoHeaderIdentify ||
111	         key == kTilingSolverHeaderIdentify || key == kTilingApiHeaderIdentify || key == kTilingBaseHeaderIdentify ||
112	         key == kTilingEntryHeaderIdentify || key == kTilingTailHeaderIdentify;
113	}
114	
115	std::string RemoveSplitCppIncludes(const std::string &content);
116	
117	Status CombineTilings(const std::map<std::string, std::string> &tiling_file_name_to_content, std::string &result) {
118	  GE_CHK_BOOL_RET_STATUS(tiling_file_name_to_content.find(kTilingHeadIdentify) != tiling_file_name_to_content.end(),
119	                         af::FAILED, "tiling_file_name_to_content has no tiling head");
120	  result += RemoveAutoFuseTilingHeadGuards(
121	      tiling_file_name_to_content.at(kTilingHeadIdentify));  // 删除头文件的宏保护，cpp文件不需要
122	
123	  // 遍历所有非 TilingHead 和 TilingData 的条目，去掉第一行后拼接
124	  for (const auto &[key, value] : tiling_file_name_to_content) {
125	    if (key == kTilingHeadIdentify || IsSplitTilingHeaderKey(key) ||
126	        key.find(kTilingDataIdentify) != std::string::npos) {
127	      continue;
128	    }
129	
130	    result += RemoveSplitCppIncludes(value);
131	
132	    if (!result.empty() && result.back() != '\n') {
133	      result += '\n';
134	    }
135	  }
136	
137	  return af::SUCCESS;
138	}
139	
140	void AppendSplitBegin(const std::string &key, std::string &result) {
141	  result += kSplitFileBegin;
142	  result += key;
143	  result += "\n";
144	}
145	
146	void AppendSplitEnd(const std::string &key, std::string &result) {
147	  if (!result.empty() && result.back() != '\n') {
148	    result += '\n';
149	  }
150	  result += kSplitFileEnd;
151	  result += key;
152	  result += "\n";
153	}
154	
155	std::string RemoveSplitCppIncludes(const std::string &content) {
156	  const std::set<std::string> split_includes = {
157	      kTilingHeadInclude,       kTilingStateHeaderInclude,      kTilingLogHeaderInclude, kTilingPgoHeaderInclude,
158	      kTilingBaseHeaderInclude, kTilingSolverHeaderInclude,     kTilingApiHeaderInclude, kTilingEntryHeaderInclude,
159	      kTilingTailHeaderInclude, kCubeKernelTilingWrapperInclude};
160	  std::istringstream input(content);
161	  std::stringstream output;
162	  std::string line;
163	  bool in_include_prefix = true;
164	  while (std::getline(input, line)) {
165	    if (in_include_prefix && !line.empty() && line.rfind("#include ", 0U) != 0U) {
166	      in_include_prefix = false;
167	    }
168	    if (!in_include_prefix || split_includes.count(line) == 0U) {
169	      output << line << '\n';
170	    }
171	  }
172	  return output.str();
173	}
174	
175	void AppendSplitSource(const std::string &key, const std::string &content, std::string &result) {
176	  AppendSplitBegin(key, result);
177	  result += content;
178	  AppendSplitEnd(key, result);
179	}
180	
181	std::string BuildSplitHeaderContent(const std::map<std::string, std::string> &tiling_file_name_to_content) {
182	  return RemoveAutoFuseTilingHeadGuards(tiling_file_name_to_content.at(kTilingHeadIdentify));
183	}
184	
185	bool ShouldSkipSplitCppSource(const std::string &key) {
186	  return key == kTilingHeadIdentify || IsSplitTilingHeaderKey(key) || key == kCubeKernelTilingWrapperHpp ||
187	         key.find(kTilingDataIdentify) != std::string::npos;
188	}
189	
190	bool HasNewSplitTilingHeaders(const std::map<std::string, std::string> &tiling_file_name_to_content) {
191	  return tiling_file_name_to_content.find(kTilingStateHeaderIdentify) != tiling_file_name_to_content.end();
192	}
193	
194	void AppendSplitHeaderSources(const std::map<std::string, std::string> &tiling_file_name_to_content, bool is_new_format,
195	                              std::string &result) {
196	  std::string tiling_head = BuildSplitHeaderContent(tiling_file_name_to_content);
197	  if (!is_new_format) {
198	    auto wrapper_header = tiling_file_name_to_content.find(kCubeKernelTilingWrapperHpp);
199	    if (wrapper_header != tiling_file_name_to_content.end()) {
200	      if (!tiling_head.empty() && tiling_head.back() != '\n') {
201	        tiling_head += '\n';
202	      }
203	      tiling_head += wrapper_header->second;
204	    }
205	    AppendSplitSource(kTilingHeadIdentify, tiling_head, result);
206	    return;
207	  }
208	  for (const auto &key : {kTilingStateHeaderIdentify, kTilingLogHeaderIdentify, kTilingPgoHeaderIdentify,
209	                          kTilingSolverHeaderIdentify, kTilingApiHeaderIdentify, kCubeKernelTilingWrapperHpp}) {
210	    auto iter = tiling_file_name_to_content.find(key);
211	    if (iter != tiling_file_name_to_content.end()) {
212	      AppendSplitSource(key, iter->second, result);
213	    }
214	  }
215	}
216	
217	Status CombineTilingsWithSplitMarkers(const std::map<std::string, std::string> &tiling_file_name_to_content,
218	                                      std::string &result) {
219	  GE_CHK_BOOL_RET_STATUS(tiling_file_name_to_content.find(kTilingHeadIdentify) != tiling_file_name_to_content.end(),
220	                         af::FAILED, "tiling_file_name_to_content has no tiling head");
221	  const bool is_new_format = HasNewSplitTilingHeaders(tiling_file_name_to_content);
222	  AppendSplitHeaderSources(tiling_file_name_to_content, is_new_format, result);
223	  for (const auto &[key, value] : tiling_file_name_to_content) {
224	    if (ShouldSkipSplitCppSource(key)) {
225	      continue;
226	    }
227	    AppendSplitSource(key, is_new_format ? value : RemoveSplitCppIncludes(value), result);
228	  }
229	  return af::SUCCESS;
230	}
231	
232	struct ScanResult {
233	  int open_braces = 0;               // 当前行的开大括号{总数
234	  int close_braces = 0;              // 当前行的闭大括号}总数
235	  int line_starts_close_braces = 0;  // 当前行首连续闭大括号数量
236	  bool has_preprocessor = false;     // 当前行是否预处理宏
237	};
238	
239	// 处理字符串状态
240	void StringState(char c, size_t i, const std::string &line, bool &in_string, char &string_char) {
241	  if (!in_string && (c == '"' || c == '\'')) {
242	    in_string = true;
243	    string_char = c;
244	  } else if (in_string && c == string_char && (i == 0 || line[i - 1] != '\\')) {
245	    in_string = false;
246	  }
247	}
248	
249	// 处理单行/多行注释状态
250	bool CommentState(char c, char next_c, size_t &i, bool in_string, bool &in_block_comment, bool &in_line_comment) {
251	  if (!in_string && !in_block_comment && !in_line_comment) {
252	    if (c == '/' && next_c == '/') {
253	      in_line_comment = true;
254	      return true;
255	    } else if (c == '/' && next_c == '*') {
256	      in_block_comment = true;
257	      i++;
258	      return true;
259	    }
260	  } else if (in_block_comment && c == '*' && next_c == '/') {
261	    in_block_comment = false;
262	    i++;
263	    return true;
264	  }
265	  return false;
266	}
267	
268	// 大括号统计
269	void BraceCount(char c, bool &in_line_start_close_brace, ScanResult &result) {
270	  if (in_line_start_close_brace && !std::isspace(static_cast<unsigned char>(c)) &&
271	      (c != '}')) {  // 判断是否仍在闭大括号行首状态
272	    in_line_start_close_brace = false;
273	  }
274	  if (c == '{') {
275	    result.open_braces++;
276	  } else if (c == '}') {
277	    result.close_braces++;
278	    if (in_line_start_close_brace) {
279	      result.line_starts_close_braces++;
280	    }
281	  }
282	}
283	
284	ScanResult ScanLine(const std::string &line, bool &in_block_comment, bool &in_string, char &string_char) {
285	  ScanResult result;
286	  bool in_line_comment = false;           // 是否在//单行注释内
287	  bool in_line_start_close_brace = true;  // 闭大括号是否在行首
288	  for (size_t i = 0; i < line.length(); ++i) {
289	    char c = line[i];
290	    char next_c = (i + 1 < line.length()) ? line[i + 1] : '\0';
291	    // 1.1 字符串状态判断
292	    if (!in_block_comment && !in_line_comment) {
293	      StringState(c, i, line, in_string, string_char);
294	    }
295	    // 1.2 单行/多行注释状态判断
296	    bool should_continue = CommentState(c, next_c, i, in_string, in_block_comment, in_line_comment);
297	    if (should_continue) {
298	      if (in_line_comment) break;
299	      continue;
300	    }
301	    // 1.3 不在字符串或注释状态，统计大括号数量
302	    if (!in_string && !in_block_comment && !in_line_comment) {
303	      BraceCount(c, in_line_start_close_brace, result);
304	    }
305	    // 1.4 是否是宏判断
306	    if (!in_string && !in_block_comment && !in_line_comment && i == line.find_first_not_of(" \t") && c == '#') {
307	      result.has_preprocessor = true;
308	    }
309	  }
310	  return result;
311	}
312	
313	std::string FormatIndentation(const std::string &code) {
314	  std::istringstream iss(code);
315	  std::ostringstream oss;
316	  std::string line;
317	  int indent_level = 0;           // 当前缩进层级
318	  bool in_block_comment = false;  // 是否在/* */多行注释内
319	  bool in_string = false;         // 是否在字符串常量内
320	  char string_char = '\0';        // 字符串的引号类型
321	
322	  // 逐行遍历处理
323	  while (std::getline(iss, line)) {
324	    if (line.empty() || line.find_first_not_of(" \t\r\n") == std::string::npos) {
325	      oss << "\n";
326	      continue;
327	    }
328	
329	    // 阶段1 单行扫描
330	    ScanResult result = ScanLine(line, in_block_comment, in_string, string_char);
331	
332	    // 阶段2 格式化缩进
333	    std::string trimmed = line;
334	    // 2.1 去掉全部前导空格
335	    trimmed.erase(0, trimmed.find_first_not_of(" \t"));
336	    // 2.2 宏不做缩进处理
337	    if (result.has_preprocessor) {
338	      oss << trimmed << "\n";
339	      continue;
340	    }
341	    // 2.3 按照缩进等级增加缩进
342	    int current_indent = indent_level;          // 当前缩进等级
343	    if (result.line_starts_close_braces > 0) {  // 如果行首有闭大括号，先减少缩进（用于当前行）
344	      current_indent = std::max(0, indent_level - result.line_starts_close_braces);
345	    }
346	
347	    // 阶段3 输出当前行
348	    oss << std::string(current_indent * 2, ' ') << trimmed << "\n";
349	
350	    // 更新下一行的缩进等级
351	    indent_level = indent_level - result.close_braces + result.open_braces;
352	    indent_level = std::max(0, indent_level);
353	  }
354	  return oss.str();
355	}
356	
357	}  // namespace
