359	std::string RemoveSubDirInclude(const std::string &kernel_str) {
360	  std::string result = R"(
361	#include "kernel_operator.h"
362	)";
363	  std::stringstream ss(kernel_str);
364	  std::string line;
365	  while (std::getline(ss, line)) {
366	    auto shouldRemove = [&line]() {
367	      return line.compare(0, kBasicApiInclude.size(), kBasicApiInclude) == 0 ||
368	             line.compare(0, kAdvApiInclude.size(), kAdvApiInclude) == 0 ||
369	             line.compare(0, kMicroApiInclude.size(), kMicroApiInclude) == 0 ||
370	             line.compare(0, kSimtApiInclude.size(), kSimtApiInclude) == 0 ||
371	             line.compare(0, kUtilsStdInclude.size(), kUtilsStdInclude) == 0;
372	    };
373	    if (!shouldRemove()) {
374	      result += line + "\n";
375	    }
376	  }
377	  return result;
378	}
