390	// inductor路径仍返回单个host_tiling字符串，通过注释marker保留拆分边界
391	Status Codegen::GenerateForInductor(const ascir::FusedScheduledResult &fused_schedule_result,
392	                                    CodegenResult &result) const {
393	  if (tiling_lib_.ShouldFallbackPgo(fused_schedule_result)) {
394	    GELOGW("Tiling key count exceeds 10000, fallback to non-PGO Inductor codegen");
395	    Codegen fallback(*this);
396	    fallback.tiling_lib_.DisableInductorPgo();
397	    return fallback.GenerateForInductor(fused_schedule_result, result);
398	  }
399	  const auto generate_tiling_without_pgo = [&]() {
400	    if (!tiling_lib_.IsInductorPgoEnabled() || ascgen_utils::IsCubeFusedScheduled(fused_schedule_result) ||
401	        !ascgen_utils::IsStaticSchedResult(fused_schedule_result)) {
402	      return af::FAILED;
403	    }
404	    GELOGW("Inductor PGO codegen failed, fallback to non-PGO codegen for static non-CV kernel");
405	    Codegen fallback(*this);
406	    fallback.tiling_lib_.DisableInductorPgo();
407	    return fallback.GenerateForInductor(fused_schedule_result, result);
408	  };
409	  GE_CHK_STATUS_RET(GenerateKernel(fused_schedule_result, result.kernel, true), "Codegen generate kernel failed");
410	  result.tiling_data = GenerateTilingData(fused_schedule_result, true);
411	  std::map<std::string, std::string> tiling_file_name_to_content;
412	  const auto tiling_ret = GenerateTilingForInductor(fused_schedule_result, tiling_file_name_to_content);
413	  if (tiling_ret != af::SUCCESS) {
414	    if (generate_tiling_without_pgo() == af::SUCCESS) {
415	      return af::SUCCESS;
416	    }
417	    GE_CHK_STATUS_RET(tiling_ret, "Codegen generate tiling failed");
418	  }
419	  const auto pgo_runner = tiling_file_name_to_content.find(kPgoRunnerIdentify);
420	  if (pgo_runner != tiling_file_name_to_content.end()) {
421	    GE_CHK_BOOL_RET_STATUS(!pgo_runner->second.empty() && !result.kernel.empty(), af::FAILED,
422	                           "Inductor PGO runner or device source is empty");
423	    tiling_file_name_to_content[kPgoDeviceSourceIdentify] = result.kernel;
424	  }
425	  GE_CHK_STATUS_RET(CombineTilingsWithSplitMarkers(tiling_file_name_to_content, result.tiling));
426	  return af::SUCCESS;
427	}
