496	Status Codegen::GenerateKernel(const ascir::FusedScheduledResult &fused_schedule_result, std::string &result,
497	                               bool is_inductor) const {
498	  ascir::utils::FusedGraphNameGuard guard(fused_schedule_result.fused_graph_name.GetString());
499	  GE_CHK_STATUS_RET(EnrichScheduledResultAscirParams(fused_schedule_result), "Enrich ascir node params failed.");
500	  const auto io_num = fused_schedule_result.input_nodes.size() + fused_schedule_result.output_nodes.size();
501	  bool use_list_tensor = io_num >= kMaxUnfoldedIoNum;
502	  CodegenConfig config = {is_inductor, using_att_calc_qbt_size_};
503	  if (is_inductor) {
504	    use_list_tensor = false;
505	    GE_LOGW_IF(io_num >= kKernelMaxIoNum, "Too many io, io num is %zu", io_num);
506	  }
507	  std::string graph_name = ascgen_utils::GenValidName(fused_schedule_result.fused_graph_name.GetString());
508	  GELOGI("kernel_name = %s, num_inputs = %zu, num_outputs = %zu, use list tensor desc = %d", graph_name.c_str(),
509	         fused_schedule_result.input_nodes.size(), fused_schedule_result.output_nodes.size(),
510	         static_cast<int32_t>(use_list_tensor));
511	  std::stringstream ss;
512	  std::string kernel_task_type = GetKernelTaskType(fused_schedule_result);
513	  ss << Kernel::IncludeAndDefines(fused_schedule_result, kernel_task_type, use_list_tensor, is_inductor);
514	  GE_CHK_STATUS_RET(
515	      Kernel::GenKernelFuncByTilingKey(fused_schedule_result, ss, use_list_tensor, config, kernel_task_type),
516	      "Generate kernel func by tiling_key failed.");
517	  if (is_inductor) {
518	    ss << Kernel::GenKernelFuncCallForInductor(fused_schedule_result);
519	  }
520	  result = FormatIndentation(ss.str());
521	  return af::SUCCESS;
522	}
