524	std::string Codegen::GenGetKernelAndJson(const std::string &kernel_path, const std::string &json_path) const {
525	  // 当前只获取kernel，后续计划json也会打包起来
526	  (void)json_path;
527	  std::stringstream ss;
528	  std::string real_kernel_path;
529	  if (!ascgen_utils::GetRealPath(kernel_path, real_kernel_path)) {
530	    GELOGE(af::FAILED, "kernel_path::%s realpath failed", kernel_path.c_str());
531	    return "";
532	  }
533	  std::ifstream kernel_file(real_kernel_path, std::ios::binary | std::ios::ate);
534	  if (!kernel_file.is_open()) {
535	    GELOGE(af::FAILED, "kernel_path::%s open failed", kernel_path.c_str());
536	    return "";
537	  }
538	
539	  std::streamsize kernel_file_size = kernel_file.tellg();
540	  kernel_file.seekg(0, std::ios::beg);
541	  std::vector<uint8_t> kernel_data(kernel_file_size);
542	  kernel_file.read(reinterpret_cast<char *>(kernel_data.data()), kernel_file_size);
543	  kernel_file.close();
544	
545	  ss << "#include <cstdint>" << std::endl;
546	  ss << "#include <cstring>" << std::endl;
547	  ss << "#include <vector>" << std::endl;
548	  ss << "extern \"C\" void GetKernelBin(std::vector<char> &kernel_bin) {" << std::endl;
549	  if (kernel_file_size == 0) {
550	    ss << "  std::vector<uint8_t> temp_kernel = {};" << std::endl;
551	    ss << "  return;" << std::endl;
552	  } else {
553	    ss << "  static const uint8_t temp_kernel[] = {";
554	    for (uint32_t i = 0; i < kernel_file_size; i++) {
555	      if (i % ELEMENTS_PER_LINE == 0) {
556	        ss << std::endl << "    ";
557	      }
558	      ss << std::to_string(kernel_data[i]) << ", ";
559	    }
560	    ss << "};" << std::endl;
561	
562	    ss << "  kernel_bin.resize(sizeof(temp_kernel));" << std::endl;
563	    ss << "  std::memcpy(kernel_bin.data(), temp_kernel, sizeof(temp_kernel));" << std::endl;
564	  }
565	  ss << "}";
566	  return ss.str();
567	}
